import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.7nMnW4XS.js";const u=JSON.parse('{"title":"ADR-070 — Split docs deploy from app deploy (CI-gated docs, e2e-gated app)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-070.md","filePath":"adr/ADR-070.md"}'),s={name:"adr/ADR-070.md"};function r(l,e,d,n,c,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-070-—-split-docs-deploy-from-app-deploy-ci-gated-docs-e2e-gated-app" tabindex="-1">ADR-070 — Split docs deploy from app deploy (CI-gated docs, e2e-gated app) <a class="header-anchor" href="#adr-070-—-split-docs-deploy-from-app-deploy-ci-gated-docs-e2e-gated-app" aria-label="Permalink to &quot;ADR-070 — Split docs deploy from app deploy (CI-gated docs, e2e-gated app)&quot;">​</a></h1><blockquote><p>Status · Accepted (gate workflow renamed from <code>e2e.yml</code> to <code>docker-e2e.yml</code> by ADR-071) Date · 2026-05-28 Closes into · <code>.github/workflows/deploy-docs.yml</code> + <code>preview.yml</code> Related ADRs · ADR-014 (CI / pipeline chain), ADR-016 (asset freshness cron), <strong>ADR-071 (e2e/docker-e2e consolidation — the <code>e2e</code> workflow this ADR refers to has been folded into <code>docker-e2e</code>)</strong> Related fix · <code>82fb49b4d</code> (VitePress <code>{‌{ }}</code> Vue interpolation escape)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Until today, the orrery GH Pages publish chain was a single linear pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push to main → ci.yml → e2e.yml → preview.yml → gh-pages</span></span></code></pre></div><p><code>preview.yml</code> built BOTH the app bundle (<code>npm run build</code>) AND the docs site (<code>npm run docs:build</code>), then published the entire <code>build/</code> (with <code>build/docs/</code> overlaid) to the gh-pages branch. The <code>workflow_run</code> trigger required the upstream <code>e2e</code> workflow to complete with <code>conclusion: success</code> before this final deploy fired.</p><p>The coupling was deliberate — <em>don&#39;t ship broken app code to the public preview</em>. But the same gate also blocks docs from shipping when e2e fails for reasons unrelated to docs correctness.</p><p>The failure mode that triggered this ADR (2026-05-27 → 28):</p><ol><li>A VitePress build error (<code>docs/adr/ADR-064.md</code>&#39;s inline <code>${‌{ secrets.* }}</code> was parsed by Vue&#39;s compiler-sfc as template interpolation) failed Deploy preview.</li><li>The fix landed in commit <code>82fb49b4d</code> ~30 min later.</li><li>But Deploy preview never re-fired automatically on the fix commit because the <strong>mobile e2e suite was independently red</strong> on a parallel-agent push (mars-tier3-panorama exit-button click flake on mobile-chromium). The fix sat on main, validated by <code>npm run docs:build</code> locally, but not deployed.</li><li>Resolved temporarily by manual <code>workflow_dispatch</code> — but the underlying coupling remains.</li></ol><p>This is the third time in recent memory the e2e gate has blocked an unrelated deploy:</p><ul><li>v0.6.0 → v0.6.1: four-round CI ping-pong from mobile-only failures blocked the tag deploy</li><li>2026-05-25: visual:69 + science-tabs baseline mismatch held up the deploy of mobile fixes</li><li>2026-05-27: VitePress fix held up by parallel agent&#39;s mobile-test work (this incident)</li></ul><p>In all three cases, the failure didn&#39;t actually mean the deploy target was broken — it meant a sibling test was flaky.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Split the deploy chain into two workflows, gated independently:</strong></p><ul><li><code>deploy-docs.yml</code> — fires on <strong>CI success</strong> on main. Builds + publishes only <code>build/docs/</code> to gh-pages, with <code>keep_files: true</code> so the previously-published app bundle stays intact.</li><li><code>preview.yml</code> — stays as is in scope, but now fires only the <strong>app bundle + docs together</strong> deploy on <strong>e2e success</strong>. Continues to publish the full <code>build/</code> (overwrites existing docs subdir with whatever it builds, which is the same docs content from the same <code>npm run docs:build</code>).</li></ul><p>Shared concurrency group <code>gh-pages-publish</code> (with <code>cancel-in-progress: false</code>) serializes both workflows on the gh-pages branch so a docs-deploy and app-deploy in flight don&#39;t race.</p><h3 id="what-this-changes-operationally" tabindex="-1">What this changes operationally <a class="header-anchor" href="#what-this-changes-operationally" aria-label="Permalink to &quot;What this changes operationally&quot;">​</a></h3><ul><li><strong>Docs fixes</strong> ship as soon as CI passes, regardless of e2e state. Typical wall-clock: 5-10 min push-to-live.</li><li><strong>App bundle</strong> still gated on full e2e (desktop + mobile-chromium). No change in the safety guarantee for the runtime app.</li><li><strong>GH Pages</strong> sees two distinct commits per main push: one for docs (CI-gated) and one for app+docs (e2e-gated, lands a few minutes later). The docs subdir is touched twice — first by <code>deploy-docs.yml</code> (via <code>destination_dir: docs</code> + <code>keep_files: true</code>), then by <code>preview.yml</code> (full <code>publish_dir: ./build</code>).</li></ul><h3 id="why-keep-files-true-for-the-docs-deploy" tabindex="-1">Why <code>keep_files: true</code> for the docs deploy <a class="header-anchor" href="#why-keep-files-true-for-the-docs-deploy" aria-label="Permalink to &quot;Why `keep_files: true` for the docs deploy&quot;">​</a></h3><p>The peaceiris/actions-gh-pages action&#39;s default behaviour is to wipe the publish_dir&#39;s contents on the target branch and replace with the new artefact. For a docs-only deploy that would wipe the app bundle — exactly the regression this ADR is trying to prevent. <code>keep_files: true</code> makes the action overlay-style — only files within <code>destination_dir: docs</code> get touched.</p><h3 id="why-a-shared-concurrency-group-instead-of-separate-ones" tabindex="-1">Why a shared concurrency group instead of separate ones <a class="header-anchor" href="#why-a-shared-concurrency-group-instead-of-separate-ones" aria-label="Permalink to &quot;Why a shared concurrency group instead of separate ones&quot;">​</a></h3><p><code>cancel-in-progress: false</code> means each workflow&#39;s run waits for any other run in the group to finish before starting. Without that, a docs-deploy and an app-deploy could land at exactly the same time and one of them would fail with <code>Updates were rejected because the remote contains work that you do not have locally</code>. Single-group serialization avoids that without losing parallelism on workflows that don&#39;t touch gh-pages.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Docs fixes ship independent of e2e flakiness.</strong> The dominant motivating case: VitePress / sidebar / typography fixes are docs-correctness changes that don&#39;t touch app code, but used to be held hostage by mobile-only e2e flakes.</li><li><strong>Faster docs feedback loop.</strong> 5-10 min CI vs 25-30 min full pipeline. Useful when iterating on architecture docs / ADR layouts.</li><li><strong>Same app-deploy safety net.</strong> <code>preview.yml</code>&#39;s e2e gate is preserved. No regression in &quot;don&#39;t ship broken app to public preview&quot;.</li><li><strong>No new dependency.</strong> Both workflows use the same <code>peaceiris/actions-gh-pages@v4</code> action with different config; no new actions or services introduced.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Two GH Pages commits per push</strong> instead of one — slightly noisier git history on the gh-pages branch. Not user-visible; gh-pages content is the deploy artefact, not a reviewable surface.</li><li><strong>A docs change that depends on a coordinated app change</strong> (rare — e.g. linking docs to a new app route) can ship first via deploy-docs, leaving a brief window of dead-link-to-not-yet-deployed-route. Mitigation: rely on <code>npm run preflight</code>&#39;s link validation locally for that specific case, or stage the coordinated change so docs land after app.</li><li><strong>The shared concurrency group introduces some serialization.</strong> A burst of pushes will see deploys queue up. Practical impact: minimal (deploys are rare events; serialization adds at most a few minutes to the second deploy in a burst).</li></ul><h3 id="neutral" tabindex="-1">Neutral <a class="header-anchor" href="#neutral" aria-label="Permalink to &quot;Neutral&quot;">​</a></h3><ul><li><strong>Both workflows continue to support <code>workflow_dispatch</code></strong> for manual re-runs (useful for the recovery case the May 2026 incident used).</li><li><strong>The Monday-06:00-UTC weekly cron</strong> stays on <code>preview.yml</code> (full app+docs rebuild for asset freshness per ADR-016).</li></ul><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>If we add a public app domain in production (separate from the preview gh-pages site — RFC-024 / GH #260 phase 2), the docs split may not be needed there; the docs site could be its own gh-pages subdomain entirely. But for the preview chain, the split lands today.</p><h2 id="trail" tabindex="-1">Trail <a class="header-anchor" href="#trail" aria-label="Permalink to &quot;Trail&quot;">​</a></h2><ul><li>Original incident: 2026-05-27 23:00 UTC — VitePress build error on <code>docs/adr/ADR-064.md</code> blocked Deploy preview.</li><li>Fix landed: <code>82fb49b4d</code> (the VitePress <code>{‌{ }}</code> ZWNJ escape pattern across 9 docs files).</li><li>Manual recovery: <code>gh workflow run &quot;Deploy preview&quot; --ref main</code> at 2026-05-28 03:50 UTC fired the chain regardless of e2e state, validated the fix end-to-end, and updated gh-pages.</li><li>This ADR + split workflows: 2026-05-28.</li></ul>',33)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
